"use strict";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useEnhanceVotingRewardsWithMulticall } from "hooks/useEnhanceVotingRewardsWithMulticall";
import { Flex, Text } from "ui/src";
import SingleVotingRewards from "./SingleVotingRewards";
import VotingRewardsModal from "./VotingRewardsModal";
import VotingRewardsTop from "./VotingRewardsTop";
const MAX_VISIBLE_LOCKS = 3;
const MAX_QUEUE_SIZE = 5;
export default function VotingRewards() {
  const { address } = useAccount();
  const { data: locks = [], isLoading } = useVeABXUserLocks(address);
  const {
    results: rewardsByLock,
    isLoading: isRewardsLoading,
    error: rewardsError,
    refetch: refetchRewards
  } = useEnhanceVotingRewardsWithMulticall(locks);
  const votedLocks = useMemo(() => {
    return locks.filter((lock) => {
      const rewards = rewardsByLock[lock.id];
      return rewards ? rewards.votedPools.length > 0 || rewards.rewards.length > 0 : false;
    });
  }, [locks, rewardsByLock]);
  const hasVotedLocks = votedLocks.length > 0;
  const loading = isLoading || isRewardsLoading;
  const [claimedLockIds, setClaimedLockIds] = useState({});
  const [visibleLockQueue, setVisibleLockQueue] = useState([]);
  const defaultRewardsResult = useMemo(
    () => ({
      votedPools: [],
      rewards: [],
      canClaim: false,
      isLoading: isRewardsLoading,
      error: rewardsError,
      usedVeAbx: "0",
      refetch: refetchRewards
    }),
    [isRewardsLoading, rewardsError, refetchRewards]
  );
  const locksById = useMemo(() => {
    return new Map(locks.map((lock) => [lock.id, lock]));
  }, [locks]);
  const rawClaimableLockIds = useMemo(() => {
    return votedLocks.filter((lock) => {
      const rewards = rewardsByLock[lock.id] ?? defaultRewardsResult;
      return rewards.canClaim;
    }).map((lock) => lock.id);
  }, [votedLocks, rewardsByLock, defaultRewardsResult]);
  useEffect(() => {
    setClaimedLockIds((prev) => {
      const next = { ...prev };
      let changed = false;
      Object.keys(next).forEach((lockId) => {
        if (!rawClaimableLockIds.includes(lockId)) {
          delete next[lockId];
          changed = true;
        }
      });
      return changed ? next : prev;
    });
  }, [rawClaimableLockIds]);
  const claimableLockCandidates = useMemo(
    () => rawClaimableLockIds.filter((lockId) => !claimedLockIds[lockId]),
    [rawClaimableLockIds, claimedLockIds]
  );
  useEffect(() => {
    setVisibleLockQueue((current) => {
      const existing = current.filter((lockId) => claimableLockCandidates.includes(lockId));
      const newIds = claimableLockCandidates.filter((lockId) => !existing.includes(lockId));
      const combined = [...existing, ...newIds].slice(0, MAX_QUEUE_SIZE);
      const isSameLength = combined.length === current.length;
      if (isSameLength && combined.every((id, idx) => id === current[idx])) {
        return current;
      }
      return combined;
    });
  }, [claimableLockCandidates]);
  const locksToRender = useMemo(() => {
    return visibleLockQueue.slice(0, MAX_VISIBLE_LOCKS).map((lockId) => locksById.get(lockId)).filter((lock) => Boolean(lock));
  }, [visibleLockQueue, locksById]);
  const handleLockClaimed = useCallback((lockId) => {
    setClaimedLockIds((prev) => {
      if (prev[lockId]) {
        return prev;
      }
      return { ...prev, [lockId]: true };
    });
    setVisibleLockQueue((prev) => prev.filter((id) => id !== lockId));
  }, []);
  return <Flex marginTop={"$spacing36"}>
      <VotingRewardsTop />

      <Flex className="locks" mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
        {loading ? (
    // Show simple loading state
    <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
            <Text variant="body2" color={"$neutral2"} textAlign="center">
              Loading voting rewards...
            </Text>
          </Flex>
  ) : hasVotedLocks ? (
    // Show voting rewards for locks that have voted
    <>
            {locksToRender.map((lock) => <SingleVotingRewards
      key={lock.id}
      lock={lock}
      votingRewards={rewardsByLock[lock.id] ?? defaultRewardsResult}
      onLockClaimed={handleLockClaimed}
    />)}
            {
      /* Show empty state if no claimable rewards after loading */
    }
            {claimableLockCandidates.length === 0 && <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
                <Text variant="body2" color={"$neutral2"} textAlign="center">
                  No voting rewards available. Vote for pools with your veABX locks to start earning rewards.
                </Text>
              </Flex>}
          </>
  ) : (
    // Show empty state when no voted locks exist
    <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
            <Text variant="body2" color={"$neutral2"} textAlign="center">
              No voting rewards available. Vote for pools with your veABX locks to start earning rewards.
            </Text>
          </Flex>
  )}
      </Flex>

      <VotingRewardsModal />
    </Flex>;
}
