"use strict";
import { useAccount } from "hooks/useAccount";
import { useModalState } from "hooks/useModalState";
import { useVeABXUserLocks, useManagedVeABXRelays } from "hooks/useVeABXLocks";
import { useManagedDeposits, useRelayStatuses } from "hooks/useManagedDeposits";
import { useChainId } from "wagmi";
import { useMemo } from "react";
import { Link } from "react-router-dom";
import { Flex, Text } from "ui/src";
import { QuestionInCircle } from "ui/src/components/icons";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import SingleLock from "./SingleLock";
import TokenomicsModal from "./TokenomicsModal";
export default function Locks() {
  const { toggleModal: toggleTokenomicsModal } = useModalState(ModalName.Tokenomics);
  const { address } = useAccount();
  const rawChainId = useChainId();
  const resolvedChainId = useMemo(() => {
    if (rawChainId === UniverseChainId.Mainnet || rawChainId === UniverseChainId.Sepolia) {
      return rawChainId;
    }
    return UniverseChainId.Mainnet;
  }, [rawChainId]);
  const { data: locks = [], isLoading } = useVeABXUserLocks(address, true, resolvedChainId);
  const { depositMap, isLoading: managedLoading } = useManagedDeposits(locks);
  const { data: relayLocks = [], isLoading: relaysLoading } = useManagedVeABXRelays(true, resolvedChainId);
  const relayIds = useMemo(() => relayLocks.map((relay) => relay.id), [relayLocks]);
  const { statusMap: relayStatusMap } = useRelayStatuses(relayIds);
  const relayMap = useMemo(() => new Map(relayLocks.map((relay) => [relay.id, relay])), [relayLocks]);
  const hasLocks = locks.length > 0;
  const isLoadingOverall = isLoading || managedLoading || relaysLoading;
  return <Flex marginTop={"$spacing36"}>
      <Flex className="top" row gap={"$spacing8"} alignItems="center">
        <Text variant={"subheading1"}>Locks</Text>
        <span
    style={{
      height: 17
    }}
    onClick={toggleTokenomicsModal}
  >
          <QuestionInCircle
    color={"$neutral2"}
    cursor="pointer"
    hoverStyle={{ color: "$neutral3" }}
    size={"$icon.20"}
  />
        </span>
      </Flex>
      
      <Flex className="locks" mt={"$spacing18"} flexDirection="column" gap={"$gap24"}>
        {isLoadingOverall ? (
    // Show loading state with mock cards
    Array.from({ length: 2 }, (_, index) => <SingleLock key={`loading-${index}`} isLoading={true} />)
  ) : hasLocks ? (
    // Show real locks
    locks.map((lock) => <SingleLock
      key={lock.id}
      lock={lock}
      managedDeposit={depositMap.get(lock.id)}
      relay={depositMap.get(lock.id)?.managedTokenId ? relayMap.get(depositMap.get(lock.id).managedTokenId) : void 0}
      relayIsActive={depositMap.get(lock.id)?.managedTokenId ? relayStatusMap.get(depositMap.get(lock.id).managedTokenId)?.isActive !== false : void 0}
    />)
  ) : (
    // Show empty state with call-to-action
    <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
      flexDirection="column"
      gap={"$spacing16"}
    >
            <Text variant="body2" color={"$neutral2"} textAlign="center">
              No veABX locks found. Lock ABX to participate in governance and earn voting rewards.
            </Text>
            <Link to="/lock" className="text-decoration-none">
              <Flex
      py={"$spacing12"}
      px={"$spacing20"}
      borderRadius={"$rounded12"}
      backgroundColor={"$accent1"}
      transition="all 0.2s ease"
      hoverStyle={{ backgroundColor: "$accent1Hovered" }}
    >
                <Text variant="buttonLabel3" color={"$neutral1"}>
                  Create Lock
                </Text>
              </Flex>
            </Link>
          </Flex>
  )}
      </Flex>
      
      {
    /* <DepositeLockTextLink /> */
  }
      <TokenomicsModal />
    </Flex>;
}
