"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { useClaimAndLock } from "hooks/useClaimAndLock";
import { useUnlockFlow } from "hooks/useUnlockFlow";
import { useVeABXRewards } from "hooks/useVeABXRewards";
import {
  formatRewardAmount,
  useVotingRewardsFromSubgraph,
  groupRewardsByType
} from "hooks/useVotingRewardsFromSubgraph";
import { Lock } from "react-feather";
import { Link } from "react-router-dom";
import { Button } from "tamagui";
import { Flex, Separator, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { calculateTimeUntilUnlock } from "utils/lockCalculations";
export default function SingleLock({ lock, isLoading, managedDeposit, relay, relayIsActive }) {
  const colors = useSporeColors();
  const rewardData = useVeABXRewards(lock);
  const { rewards, canClaim } = useVotingRewardsFromSubgraph(lock);
  const { fees, bribes } = groupRewardsByType(rewards);
  const totalValueUSD = "0";
  const { claimAndLock, isLoading: isClaimLoading } = useClaimAndLock(lock);
  const { executeUnlock, isProcessing: isUnlockProcessing, flowState } = useUnlockFlow();
  const isLockExpired = lock && !lock.permanent ? calculateTimeUntilUnlock(lock.lockEnd).expired : false;
  const lockId = lock?.id ? `#${lock.id.slice(-6)}` : "#83065";
  const lockAmount = lock?.amount ? (parseFloat(lock.amount) / 1e18).toFixed(3) : "0.05";
  const votingPower = lock?.votingPower ? (parseFloat(lock.votingPower) / 1e18).toFixed(6) : "0.00004";
  const managedRelayId = managedDeposit?.isDeposited ? managedDeposit.managedTokenId ?? null : null;
  const isRelayDeposited = Boolean(managedRelayId);
  const relayLabel = managedRelayId ? `mveABX #${managedRelayId}` : null;
  const relayStatusText = managedRelayId ? relayIsActive === false ? " (Relay paused)" : " (Auto-compounding)" : "";
  const lockEndTime = lock?.lockEnd ? new Date(parseInt(lock.lockEnd) * 1e3) : null;
  const timeRemaining = lockEndTime ? lockEndTime > /* @__PURE__ */ new Date() ? Math.ceil((lockEndTime.getTime() - Date.now()) / (1e3 * 60 * 60 * 24 * 365.25)) : 0 : 2;
  const rebaseAPR = rewardData.rebaseAPR || "N/A";
  const totalClaimableValue = parseFloat(totalValueUSD);
  const hasClaimableRewards = canClaim && totalClaimableValue > 0;
  const primaryReward = fees.length > 0 ? fees[0] : bribes.length > 0 ? bribes[0] : null;
  const primaryRewardAmount = primaryReward ? formatRewardAmount(primaryReward.amount, primaryReward.token.decimals) : "0";
  const primaryRewardSymbol = primaryReward?.token.symbol || "ABX";
  const CommonSeparation = styled(Separator, {
    display: "none",
    $lg: {
      display: "block",
      borderColor: "$surface3",
      width: "100%",
      height: 1,
      my: "$spacing12"
    }
  });
  const lockUrls = [
    {
      url: `/locks/modify-lock?lockId=${lock?.id}&tab=Increase`,
      label: "Increase"
    },
    {
      url: `/locks/modify-lock?lockId=${lock?.id}&tab=Extend`,
      label: "Extend"
    },
    {
      url: `/locks/modify-lock?lockId=${lock?.id}&tab=Merge`,
      label: "Merge"
    },
    {
      url: `/locks/modify-lock?lockId=${lock?.id}&tab=Transfer`,
      label: "Transfer"
    }
  ];
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "5fr 2fr 2fr" }}
    $lg={{
      gridTemplateColumns: "1fr"
    }}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
    width={"100%"}
    p={"$padding12"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    transition="background-color 0.2s ease"
    hoverStyle={{
      backgroundColor: "$surface1Hovered"
    }}
  >
      <Flex className="left" flexDirection="column" gap={"$gap8"}>
        <Flex row gap={"$gap12"}>
          <Flex
    height={50}
    width={50}
    centered
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    row
    style={{
      background: `linear-gradient(90deg, ${colors.surface2Hovered.variable} 0%, ${colors.surface2.variable} 40%, ${colors.surface2Hovered.variable} 60%, ${colors.slate.variable} 100%)`
    }}
  >
            <LogoProvider color={colors.neutral2Temp.val} size={24} />
          </Flex>

          <Flex flexDirection="column" justifyContent="center" gap={"$gap8"}>
            <Flex row gap={"$gap12"} alignItems="center">
              <Text>Lock {lockId}</Text> <Lock size={14} color={colors.accent1Hovered.val} />
            </Flex>
            <Text variant="body4" color={"$neutral2"}>
              {lockAmount} ABX locked for {timeRemaining} {timeRemaining === 1 ? "year" : "years"}
              {lock?.permanent && " (Permanent)"}
            </Text>
            {isRelayDeposited && <Text variant="body4" color={"$accent1"}>
                Managed by {relayLabel}
                {relayStatusText}
              </Text>}
          </Flex>
        </Flex>

        <CommonSeparation />
        <Flex row gap={"$gap12"} alignItems="center">
          {lockUrls.map((item, index) => <Link className="text-decoration-none" to={item.url} key={index}>
              <Text
    variant="buttonLabel3"
    color={"$neutral1Hovered"}
    transition="all 250ms ease"
    hoverStyle={{ color: "$neutral2Temp" }}
    fontSize={"$micro"}
  >
                {item.label}
              </Text>
            </Link>)}
        </Flex>
      </Flex>

      <CommonSeparation />
      <Flex
    className="rebase-apr"
    flexDirection="column"
    gap={"$gap12"}
    alignItems="flex-end"
    $lg={{ flexDirection: "row", justifyContent: "space-between" }}
  >
        <Text variant="body3" color={"$neutral2"}>
          Rebase APR
        </Text>
        <Text variant="body3" fontSize={"$mdall"}>
          {rebaseAPR}
        </Text>
      </Flex>
      <CommonSeparation />
      <Flex className="rebase-reward" flexDirection="column" justifyContent="space-between" alignItems="flex-end">
        <Flex
    flexDirection="column"
    alignItems="flex-end"
    gap={"$gap12"}
    $lg={{ flexDirection: "row", justifyContent: "space-between", alignItems: "flex-start", width: "100%" }}
  >
          <Text variant="body3" color={"$neutral2"}>
            Rewards
          </Text>
          <Flex flexDirection="column" alignItems="flex-end" gap={"$gap4"}>
            <Text variant="body3" fontSize={"$mdall"}>
              {primaryRewardAmount} {primaryRewardSymbol}
            </Text>
            {hasClaimableRewards && <Text variant="body4" color={"$neutral1"} fontSize={"$xs"}>
                ~${totalValueUSD}
              </Text>}
          </Flex>
        </Flex>
        <CommonSeparation />
        <Flex>
          {isLockExpired ? <Button
    mt={"$gap24"}
    py={"$spacing16"}
    px={"$spacing12"}
    borderRadius={"$roundedFull"}
    transition="all 0.2s ease"
    borderWidth={1}
    borderColor={"$accent1"}
    backgroundColor={"$accent1"}
    disabled={isUnlockProcessing}
    onPress={() => lock && executeUnlock(lock.id)}
    hoverStyle={{
      backgroundColor: "$accent1Hovered",
      borderColor: "$accent1Hovered"
    }}
    $md={{
      mt: "$gap12"
    }}
  >
              <Flex row alignItems="center" gap={"$gap8"}>
                {isUnlockProcessing && <SpinningLoader size={16} />}
                <Text variant="body3" fontWeight={"$medium"} color={"$white"}>
                  {isUnlockProcessing && flowState.tokenId === lock?.id ? "Unlocking" : "Unlock ABX"}
                </Text>
              </Flex>
            </Button> : <Button
    mt={"$gap24"}
    py={"$spacing16"}
    px={"$spacing12"}
    borderRadius={"$roundedFull"}
    transition="all 0.2s ease"
    borderWidth={1}
    borderColor={hasClaimableRewards ? "$accent1" : "$surface3"}
    backgroundColor={hasClaimableRewards ? "$accent1" : "$surface2"}
    opacity={hasClaimableRewards ? 1 : 0.6}
    disabled={!hasClaimableRewards || isClaimLoading}
    onPress={hasClaimableRewards ? claimAndLock : void 0}
    hoverStyle={{
      backgroundColor: hasClaimableRewards ? "$accent1Hovered" : "$surface2Hovered",
      borderColor: hasClaimableRewards ? "$accent1Hovered" : "$surface3Hovered"
    }}
    $md={{
      mt: "$gap12"
    }}
  >
              <Flex row alignItems="center" gap={"$gap8"}>
                {isUnlockProcessing && <SpinningLoader size={16} />}
                <Text variant="body3" fontWeight={"$medium"} color={hasClaimableRewards ? "$white" : "$neutral2"}>
                  {isClaimLoading ? "Claiming" : hasClaimableRewards ? "Claim & lock" : "No rewards"}
                </Text>
              </Flex>
            </Button>}
          {
    /* <button role="button" className="button-clear">
      <Text
        variant="buttonLabel3"
        px={'$padding8'}
        py={'6px'}
        borderRadius={'$rounded12'}
        backgroundColor={'$neutral3'}
        fontWeight={'$medium'}
        transition="all 250ms ease"
        hoverStyle={{ backgroundColor: '$surface1', color: '$neutral2Temp' }}
      >
        Claim & lock
      </Text>
    </button> */
  }
        </Flex>
      </Flex>
    </Flex>;
}
